// Load non-secret settings from Variables, environment, or the local fallback. Keep tokens in Credentials.
const text = (value, fallback = '') => String(value ?? fallback).trim();
const number = (value, fallback, min, max) => {
  const normalized = String(value ?? '').trim();
  if (!normalized) return fallback;
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
};
const integer = (value, fallback, min, max) => Math.round(number(value, fallback, min, max));
const boolean = (value, fallback = false) => {
  const normalized = text(value, fallback ? 'true' : 'false').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(normalized)) return true;
  if (['false', '0', 'no', 'off'].includes(normalized)) return false;
  return fallback;
};
const clean = (value, max = 200) => text(value).replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').slice(0, max);
const isSafePublicHttps = (value) => {
  try {
    const parsed = new URL(value);
    const host = parsed.hostname.toLowerCase().replace(/^\[|\]$/g, '');
    const privateHost = host === 'localhost' || host === '0.0.0.0' || host.endsWith('.local') || host.includes(':') || /^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host) || /^169\.254\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host);
    return parsed.protocol === 'https:' && !parsed.username && !parsed.password && !privateHost;
  } catch {
    return false;
  }
};

// Community Edition fallback: edit only these non-secret values if
// neither n8n Variables nor self-hosted environment access is available.
const LOCAL_CONFIG = {
  demo_mode: 'true',
  service_catalog_json: '',
  request_timeout_ms: '',
  down_after_failures: '',
  recover_after_successes: '',
  escalation_minutes: '',
  escalation_retry_minutes: '',
  rolling_sample_limit: '',
  metrics_retention_days: '',
  slo_target_percent: '',
  telegram_chat_id: '',
  jira_base_url: '',
  jira_project_key: '',
  jira_issue_type: '',
  jira_resolve_transition_id: ''
};
const setting = (name, localKey, fallback = '') => {
  let candidate;
  try { candidate = $vars?.[name]; } catch {}
  if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') return candidate;
  try { candidate = $env?.[name]; } catch {}
  if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') return candidate;
  candidate = LOCAL_CONFIG[localKey];
  return candidate !== undefined && candidate !== null && String(candidate).trim() !== '' ? candidate : fallback;
};

const now = Date.now();
const demoMode = boolean(setting('PULSEOPS_DEMO_MODE', 'demo_mode', 'true'), true);
const DEMO_SERVICES = [
  { id: 'public-web', name: 'Public Website', url: 'https://example.com', expected_statuses: [200], latency_threshold_ms: 700, criticality: 'high', demo_result: { status_code: 200, latency_ms: 182 }, demo_previous: { state: 'healthy', consecutive_failures: 0, consecutive_successes: 5 } },
  { id: 'auth-api', name: 'Authentication API', url: 'https://api.example.com/auth/health', expected_statuses: [200], latency_threshold_ms: 500, criticality: 'critical', demo_result: { status_code: 503, latency_ms: 2310, error: 'Service Unavailable' }, demo_previous: { state: 'degraded', consecutive_failures: 1, consecutive_successes: 0 } },
  { id: 'payments-api', name: 'Payments API', url: 'https://api.example.com/payments/health', expected_statuses: [200], latency_threshold_ms: 650, criticality: 'critical', demo_result: { status_code: 200, latency_ms: 314 }, demo_previous: { state: 'down', consecutive_failures: 3, consecutive_successes: 1, incident_id: 'inc_demo_payments', jira_issue_key: 'OPS-DEMO-421', status_page_incident_id: 'status_demo_payments', down_since: now - 22 * 60 * 1000 } },
  { id: 'search-api', name: 'Search API', url: 'https://api.example.com/search/health', expected_statuses: [200], latency_threshold_ms: 800, criticality: 'medium', demo_result: { status_code: 200, latency_ms: 1248 }, demo_previous: { state: 'healthy', consecutive_failures: 0, consecutive_successes: 8 } },
  { id: 'webhook-worker', name: 'Webhook Worker', url: 'https://api.example.com/webhooks/health', expected_statuses: [200, 204], latency_threshold_ms: 900, criticality: 'high', demo_result: { status_code: 204, latency_ms: 271 }, demo_previous: { state: 'healthy', consecutive_failures: 0, consecutive_successes: 12 } }
];

let serviceCatalog = DEMO_SERVICES;
if (!demoMode) {
  const rawCatalog = text(setting('PULSEOPS_SERVICE_CATALOG_JSON', 'service_catalog_json'));
  if (!rawCatalog) throw new Error('Missing live configuration: PULSEOPS_SERVICE_CATALOG_JSON');
  try {
    serviceCatalog = JSON.parse(rawCatalog);
  } catch {
    throw new Error('PULSEOPS_SERVICE_CATALOG_JSON must be valid JSON');
  }
}
if (!Array.isArray(serviceCatalog) || serviceCatalog.length === 0 || serviceCatalog.length > 100) {
  throw new Error('Service catalog must contain between 1 and 100 services');
}

const seenIds = new Set();
const services = serviceCatalog.map((raw, index) => {
  const id = clean(raw?.id, 64).toLowerCase();
  const name = clean(raw?.name, 120);
  const url = text(raw?.url).slice(0, 1500);
  const expected = Array.isArray(raw?.expected_statuses) ? raw.expected_statuses.map(Number).filter(value => Number.isInteger(value) && value >= 100 && value <= 599) : [];
  const criticality = clean(raw?.criticality || 'medium', 20).toLowerCase();
  if (!/^[a-z0-9][a-z0-9-]{1,63}$/.test(id)) throw new Error(`Service ${index + 1} has an invalid id`);
  if (seenIds.has(id)) throw new Error(`Duplicate service id: ${id}`);
  if (!name) throw new Error(`Service ${id} is missing a name`);
  if (!isSafePublicHttps(url)) throw new Error(`Service ${id} must use a safe public HTTPS URL`);
  if (!expected.length) throw new Error(`Service ${id} needs at least one expected HTTP status`);
  if (!['low', 'medium', 'high', 'critical'].includes(criticality)) throw new Error(`Service ${id} has an invalid criticality`);
  seenIds.add(id);
  return {
    id,
    name,
    url,
    expected_statuses: [...new Set(expected)],
    latency_threshold_ms: integer(raw?.latency_threshold_ms, 1000, 50, 120000),
    criticality,
    ...(demoMode ? { demo_result: raw.demo_result || {}, demo_previous: raw.demo_previous || {} } : {})
  };
});

const config = {
  demo_mode: demoMode,
  request_timeout_ms: integer(setting('PULSEOPS_REQUEST_TIMEOUT_MS', 'request_timeout_ms'), 8000, 1000, 60000),
  down_after_failures: integer(setting('PULSEOPS_DOWN_AFTER_FAILURES', 'down_after_failures'), 2, 1, 10),
  recover_after_successes: integer(setting('PULSEOPS_RECOVER_AFTER_SUCCESSES', 'recover_after_successes'), 2, 1, 10),
  escalation_minutes: integer(setting('PULSEOPS_ESCALATION_MINUTES', 'escalation_minutes'), 15, 1, 1440),
  escalation_retry_minutes: integer(setting('PULSEOPS_ESCALATION_RETRY_MINUTES', 'escalation_retry_minutes'), 5, 1, 120),
  rolling_sample_limit: integer(setting('PULSEOPS_ROLLING_SAMPLE_LIMIT', 'rolling_sample_limit'), 288, 10, 10000),
  metrics_retention_days: integer(setting('PULSEOPS_METRICS_RETENTION_DAYS', 'metrics_retention_days'), 14, 1, 90),
  slo_target_percent: number(setting('PULSEOPS_SLO_TARGET_PERCENT', 'slo_target_percent'), 99.9, 90, 99.999),
  telegram_chat_id: text(setting('PULSEOPS_TELEGRAM_CHAT_ID', 'telegram_chat_id', demoMode ? 'DEMO_CHAT_ID' : '')),
  jira_base_url: text(setting('PULSEOPS_JIRA_BASE_URL', 'jira_base_url', demoMode ? 'https://your-domain.atlassian.net' : '')).replace(/\/+$/, ''),
  jira_project_key: clean(setting('PULSEOPS_JIRA_PROJECT_KEY', 'jira_project_key'), 20).toUpperCase() || (demoMode ? 'OPS' : ''),
  jira_issue_type: clean(setting('PULSEOPS_JIRA_ISSUE_TYPE', 'jira_issue_type'), 80) || 'Task',
  jira_resolve_transition_id: clean(setting('PULSEOPS_JIRA_RESOLVE_TRANSITION_ID', 'jira_resolve_transition_id'), 40) || (demoMode ? '31' : ''),
  services
};

if (!demoMode) {
  const missing = [];
  if (!config.telegram_chat_id) missing.push('PULSEOPS_TELEGRAM_CHAT_ID');
  if (!config.jira_base_url) missing.push('PULSEOPS_JIRA_BASE_URL');
  if (!config.jira_project_key) missing.push('PULSEOPS_JIRA_PROJECT_KEY');
  if (!config.jira_resolve_transition_id) missing.push('PULSEOPS_JIRA_RESOLVE_TRANSITION_ID');
  if (missing.length) throw new Error(`Missing live configuration: ${missing.join(', ')}`);
  if (!isSafePublicHttps(config.jira_base_url)) throw new Error('PULSEOPS_JIRA_BASE_URL must use a safe public HTTPS URL');
  if (!/^[A-Z][A-Z0-9_]{1,19}$/.test(config.jira_project_key)) throw new Error('PULSEOPS_JIRA_PROJECT_KEY is invalid');
}

return [{ json: {
  ...$input.first().json,
  config,
  run_id: `run_${now}_${Math.random().toString(36).slice(2, 10)}`
} }];

const root = $input.first().json;
return root.config.services.map((service, index) => ({
  json: {
    config: root.config,
    run_id: root.run_id,
    triggered_at: root.triggered_at,
    service_index: index,
    service
  },
  pairedItem: { item: 0 }
}));

const started = Date.now();
return $input.all().map((item, index) => ({
  json: { ...item.json, check_started_at_ms: started + index },
  pairedItem: { item: index }
}));

return $input.all().map((item, index) => {
  const data = item.json;
  const result = data.service.demo_result || {};
  const statusCode = Number(result.status_code || 0);
  const success = data.service.expected_statuses.includes(statusCode);
  return {
    json: {
      ...data,
      check: {
        success,
        status_code: statusCode,
        latency_ms: Number(result.latency_ms || 0),
        error: success ? null : (result.error || `Unexpected HTTP status ${statusCode}`),
        checked_at: new Date().toISOString(),
        response_excerpt: success ? '{"status":"ok"}' : String(result.error || 'unavailable'),
        provider: 'deterministic_demo'
      }
    },
    pairedItem: { item: index }
  };
});

return $input.all().map((item, index) => {
  const data = item.json;
  const statusCode = Number(data.statusCode ?? data.status_code ?? 0);
  const expected = Array.isArray(data.service?.expected_statuses) ? data.service.expected_statuses : [200];
  const latency = Math.max(0, Date.now() - Number(data.check_started_at_ms || Date.now()));
  const transportError = data.error?.message || data.errorMessage || data.message || null;
  const success = expected.includes(statusCode) && !transportError;
  const rawBody = typeof data.body === 'string' ? data.body : JSON.stringify(data.body ?? '');
  const excerpt = rawBody
    .replace(/(["']?(?:authorization|api[_-]?key|token|password)["']?\s*:\s*)["'][^"']*["']/gi, '$1"[REDACTED]"')
    .replace(/((?:authorization|api[_-]?key|token|password)\s*[=:]\s*)(?:Bearer\s+|Basic\s+)?[^,\s}&]+/gi, '$1[REDACTED]')
    .replace(/\bBearer\s+[A-Za-z0-9._~+/-]{8,}={0,2}/gi, 'Bearer [REDACTED]')
    .replace(/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g, '[REDACTED]')
    .replace(/\b\d{6,12}:[A-Za-z0-9_-]{20,}\b/g, '[REDACTED]')
    .replace(/[\u0000-\u001F\u007F]/g, ' ')
    .slice(0, 300);
  return {
    json: {
      config: data.config,
      run_id: data.run_id,
      triggered_at: data.triggered_at,
      service_index: data.service_index,
      service: data.service,
      check: {
        success,
        status_code: statusCode,
        latency_ms: latency,
        error: success ? null : (transportError || `Unexpected HTTP status ${statusCode || 'unknown'}`),
        checked_at: new Date().toISOString(),
        response_excerpt: excerpt,
        provider: 'live_http'
      }
    },
    pairedItem: { item: index }
  };
});

const items = $input.all().map(item => item.json);
if (!items.length) return [];
const checks = items.map(item => ({ service: item.service, check: item.check }));
const latencies = checks.map(item => item.check.latency_ms).sort((a, b) => a - b);
const percentile = (list, p) => list.length ? list[Math.min(list.length - 1, Math.max(0, Math.ceil(list.length * p) - 1))] : 0;
const successful = checks.filter(item => item.check.success).length;
return [{ json: {
  config: items[0].config,
  run_id: items[0].run_id,
  triggered_at: items[0].triggered_at,
  checks,
  probe_summary: {
    total: checks.length,
    successful,
    failed: checks.length - successful,
    availability_percent: checks.length ? Math.round(successful / checks.length * 10000) / 100 : 0,
    p50_latency_ms: percentile(latencies, 0.5),
    p95_latency_ms: percentile(latencies, 0.95)
  }
} }];

const batch = $input.first().json;
const cfg = batch.config;
const now = Date.now();
const store = $getWorkflowStaticData('global');
store.pulseops_state = store.pulseops_state || {};
store.pulseops_metrics = store.pulseops_metrics || {};
const day = new Date(now).toISOString().slice(0, 10);
store.pulseops_metrics[day] = store.pulseops_metrics[day] || {};

if (!cfg.demo_mode) {
  const cutoff = new Date(now - cfg.metrics_retention_days * 86400000).toISOString().slice(0, 10);
  for (const metricDay of Object.keys(store.pulseops_metrics)) {
    if (metricDay < cutoff) delete store.pulseops_metrics[metricDay];
  }
}

const events = [];
const states = [];
for (const row of batch.checks) {
  const service = row.service;
  const check = row.check;
  const fallbackPrevious = {
    state: 'unknown', consecutive_failures: 0, consecutive_successes: 0,
    incident_id: null, jira_issue_key: null, status_page_incident_id: null,
    down_since: null, escalated: false, escalation_attempts: 0,
    last_escalation_attempt_at: null
  };
  const previous = cfg.demo_mode
    ? { ...fallbackPrevious, ...(service.demo_previous || {}) }
    : { ...fallbackPrevious, ...(store.pulseops_state[service.id] || {}) };
  const latencyDegraded = check.success && check.latency_ms > service.latency_threshold_ms;
  const failures = check.success ? 0 : Number(previous.consecutive_failures || 0) + 1;
  const successes = check.success ? Number(previous.consecutive_successes || 0) + 1 : 0;

  let nextState;
  if (!check.success) nextState = failures >= cfg.down_after_failures ? 'down' : 'degraded';
  else if (previous.state === 'down' && successes < cfg.recover_after_successes) nextState = 'down';
  else if (latencyDegraded) nextState = 'degraded';
  else nextState = 'healthy';

  let incidentId = previous.incident_id || null;
  let jiraIssueKey = previous.jira_issue_key || null;
  let statusPageIncidentId = previous.status_page_incident_id || null;
  let downSince = previous.down_since || null;
  let escalated = Boolean(previous.escalated);
  let escalationAttempts = Number(previous.escalation_attempts || 0);
  let lastEscalationAttemptAt = previous.last_escalation_attempt_at || null;
  let event = null;

  if (nextState === 'down' && previous.state !== 'down') {
    incidentId = `inc_${service.id}_${now}`;
    jiraIssueKey = null;
    statusPageIncidentId = null;
    downSince = now;
    escalated = false;
    escalationAttempts = 0;
    lastEscalationAttemptAt = null;
    event = {
      type: 'incident_opened', severity: 'critical', title: `${service.name} is DOWN`,
      message: check.error || `HTTP ${check.status_code}`, incident_id: incidentId,
      jira_issue_key: null, status_page_incident_id: null
    };
  } else if (previous.state === 'down' && nextState !== 'down') {
    event = {
      type: 'incident_recovered', severity: nextState === 'healthy' ? 'info' : 'warning',
      title: `${service.name} recovered from outage`,
      message: nextState === 'healthy'
        ? `Healthy after ${successes} consecutive successful checks`
        : `Reachable after ${successes} successful checks, but latency remains above threshold`,
      incident_id: previous.incident_id,
      jira_issue_key: previous.jira_issue_key || null,
      status_page_incident_id: previous.status_page_incident_id || null
    };
    incidentId = null;
    jiraIssueKey = null;
    statusPageIncidentId = null;
    downSince = null;
    escalated = false;
    escalationAttempts = 0;
    lastEscalationAttemptAt = null;
  } else if (nextState === 'degraded' && ['healthy', 'unknown'].includes(previous.state)) {
    event = {
      type: latencyDegraded ? 'performance_degraded' : 'service_degraded', severity: 'warning',
      title: `${service.name} is DEGRADED`,
      message: latencyDegraded ? `Latency ${check.latency_ms}ms exceeds ${service.latency_threshold_ms}ms` : (check.error || 'First failed check'),
      incident_id: null, jira_issue_key: null, status_page_incident_id: null
    };
  } else if (previous.state === 'degraded' && nextState === 'healthy') {
    event = {
      type: 'service_recovered', severity: 'info', title: `${service.name} returned to normal`,
      message: `Latency ${check.latency_ms}ms`, incident_id: null,
      jira_issue_key: null, status_page_incident_id: null
    };
  } else if (previous.state === 'down' && nextState === 'down' && !check.success && downSince) {
    const retryDue = !escalated && (!lastEscalationAttemptAt || now - Number(lastEscalationAttemptAt) >= cfg.escalation_retry_minutes * 60000);
    if (retryDue && now - Number(downSince) >= cfg.escalation_minutes * 60000) {
      escalationAttempts += 1;
      lastEscalationAttemptAt = now;
      event = {
        type: 'incident_escalated', severity: 'critical', title: `${service.name} incident escalated`,
        message: `Service has been down for at least ${cfg.escalation_minutes} minutes`,
        incident_id: previous.incident_id, jira_issue_key: previous.jira_issue_key || null,
        status_page_incident_id: previous.status_page_incident_id || null
      };
    }
  }

  const next = {
    service_id: service.id,
    service_name: service.name,
    state: nextState,
    previous_state: previous.state,
    consecutive_failures: failures,
    consecutive_successes: successes,
    incident_id: incidentId,
    jira_issue_key: jiraIssueKey,
    status_page_incident_id: statusPageIncidentId,
    down_since: downSince,
    escalated,
    escalation_attempts: escalationAttempts,
    last_escalation_attempt_at: lastEscalationAttemptAt,
    last_status_code: check.status_code,
    last_latency_ms: check.latency_ms,
    checked_at: check.checked_at
  };

  if (event) events.push({
    ...event,
    service_id: service.id,
    service_name: service.name,
    criticality: service.criticality,
    previous_state: previous.state,
    current_state: nextState,
    status_code: check.status_code,
    latency_ms: check.latency_ms,
    occurred_at: check.checked_at
  });
  states.push(next);

  if (!cfg.demo_mode) {
    store.pulseops_state[service.id] = next;
    const metric = store.pulseops_metrics[day][service.id] || {
      name: service.name, checks: 0, successes: 0, failures: 0,
      latencies: [], incidents: 0, recoveries: 0
    };
    metric.checks += 1;
    check.success ? metric.successes += 1 : metric.failures += 1;
    metric.latencies.push(check.latency_ms);
    if (metric.latencies.length > cfg.rolling_sample_limit) metric.latencies = metric.latencies.slice(-cfg.rolling_sample_limit);
    if (event?.type === 'incident_opened') metric.incidents += 1;
    if (event?.type === 'incident_recovered') metric.recoveries += 1;
    store.pulseops_metrics[day][service.id] = metric;
  }
}

const overallState = states.some(state => state.state === 'down')
  ? 'down'
  : states.some(state => state.state === 'degraded') ? 'degraded' : 'healthy';
return [{ json: {
  ...batch,
  state_summary: {
    overall_state: overallState,
    healthy: states.filter(state => state.state === 'healthy').length,
    degraded: states.filter(state => state.state === 'degraded').length,
    down: states.filter(state => state.state === 'down').length
  },
  service_states: states,
  events,
  event_count: events.length
} }];

const data = $input.first().json;
return [{ json: {
  success: true,
  status: data.config.demo_mode ? 'demo_stable' : 'stable',
  run_id: data.run_id,
  checked_services: data.probe_summary.total,
  overall_state: data.state_summary.overall_state,
  state_summary: data.state_summary,
  availability_percent: data.probe_summary.availability_percent,
  p95_latency_ms: data.probe_summary.p95_latency_ms,
  events: [],
  completed_at: new Date().toISOString()
} }];

const batch = $input.first().json;
return batch.events.map((event, index) => ({
  json: {
    config: batch.config,
    run_id: batch.run_id,
    probe_summary: batch.probe_summary,
    state_summary: batch.state_summary,
    event
  },
  pairedItem: { item: 0 }
}));

return $input.all().map((item, index) => {
  const data = item.json;
  const event = data.event;
  let actions;
  if (event.type === 'incident_opened') actions = { jira: 'simulated_issue_created', jira_issue_key: 'OPS-DEMO-501', telegram: 'simulated_critical_alert' };
  else if (event.type === 'incident_recovered') actions = { jira: `simulated_issue_resolved:${event.jira_issue_key || 'unknown'}`, telegram: 'simulated_recovery_alert' };
  else if (event.type === 'incident_escalated') actions = { jira: 'simulated_escalation_comment', telegram: 'simulated_escalation_alert' };
  else actions = { jira: 'not_required', telegram: 'simulated_state_change_alert' };
  return { json: { ...data, actions }, pairedItem: { item: index } };
});

const items = $input.all().map(item => item.json);
if (!items.length) return [];
return [{ json: {
  success: true,
  status: 'demo_incident_cycle_completed',
  run_id: items[0].run_id,
  overall_state: items[0].state_summary.overall_state,
  state_summary: items[0].state_summary,
  availability_percent: items[0].probe_summary.availability_percent,
  p95_latency_ms: items[0].probe_summary.p95_latency_ms,
  event_count: items.length,
  events: items.map(item => ({ ...item.event, actions: item.actions })),
  completed_at: new Date().toISOString()
} }];

return $input.all().map((item, index) => {
  const data = item.json;
  const statusCode = Number(data.statusCode ?? data.status_code ?? 0);
  const body = data.body && typeof data.body === 'object' ? data.body : {};
  const issueKey = body.key || data.key || data.jira_issue_key || null;
  const requestFailed = Boolean(data.error || data.errorMessage) || statusCode < 200 || statusCode >= 300 || !issueKey;
  const store = $getWorkflowStaticData('global');
  if (!requestFailed && store.pulseops_state?.[data.event.service_id]) {
    store.pulseops_state[data.event.service_id].jira_issue_key = issueKey;
  }
  return { json: {
    ...data,
    jira_issue_key: requestFailed ? null : issueKey,
    integration_results: { jira_creation: requestFailed ? 'failed' : 'created' },
    alert_text: `🚨 INCIDENT OPENED\n\n${data.event.service_name} is DOWN\n${data.event.message}\nHTTP: ${data.event.status_code}\nLatency: ${data.event.latency_ms}ms\nIncident: ${data.event.incident_id}\nJira: ${requestFailed ? 'creation failed' : issueKey}`
  }, pairedItem: { item: index } };
});

const base = $('Finalize Incident Integrations').item.json;
const response = $input.first().json;
const telegramFailed = response.ok === false || Boolean(response.error || response.errorMessage);
