const demoMetrics = {
  'public-web': { name: 'Public Website', checks: 288, successes: 288, failures: 0, latencies: [170, 182, 194, 211, 245], incidents: 0, recoveries: 0 },
  'auth-api': { name: 'Authentication API', checks: 288, successes: 285, failures: 3, latencies: [240, 275, 310, 490, 880], incidents: 1, recoveries: 1 },
  'payments-api': { name: 'Payments API', checks: 288, successes: 287, failures: 1, latencies: [220, 248, 271, 314, 540], incidents: 1, recoveries: 1 },
