  'webhook-worker': { name: 'Webhook Worker', checks: 288, successes: 288, failures: 0, latencies: [180, 210, 240, 271, 390], incidents: 0, recoveries: 0 }
};
const source = cfg.demo_mode ? demoMetrics : (store.pulseops_metrics?.[reportDate] || {});
const percentile = (values, p) => { const sorted = [...values].sort((a, b) => a - b); return sorted.length ? sorted[Math.min(sorted.length - 1, Math.ceil(sorted.length * p) - 1)] : 0; };
const rows = Object.entries(source).map(([id, metric]) => {
  const availability = metric.checks ? metric.successes / metric.checks * 100 : 0;
  const failurePercent = Math.max(0, 100 - availability);
  const allowedFailure = Math.max(0.0001, 100 - cfg.slo_target_percent);
  return {
    service_id: id,
    service_name: metric.name || id,
    checks: metric.checks || 0,
    availability_percent: Math.round(availability * 1000) / 1000,
    p95_latency_ms: percentile(metric.latencies || [], 0.95),
    incidents: metric.incidents || 0,
    recoveries: metric.recoveries || 0,
    error_budget_consumed_percent: Math.round(failurePercent / allowedFailure * 1000) / 10,
    slo_met: availability >= cfg.slo_target_percent
  };
});
const totalChecks = rows.reduce((sum, row) => sum + row.checks, 0);
const breaches = rows.filter(row => !row.slo_met);
const fullMessage = [
  `📊 DAILY SLO DIGEST — ${reportDate}`,
  `Target: ${cfg.slo_target_percent}%`,
  `Checks: ${totalChecks}`,
  `SLO breaches: ${breaches.length}`,
  '',
  ...rows.map(row => `${row.slo_met ? '✅' : '❌'} ${row.service_name}: ${row.availability_percent}% | p95 ${row.p95_latency_ms}ms | incidents ${row.incidents}`)
].join('\n');
const message = fullMessage.length <= 3900
  ? fullMessage
