const data = $input.first().json;
const text = (value, fallback = '') => String(value ?? fallback).trim();
const boolean = (value, fallback = false) => {
  const normalized = text(value, fallback ? 'true' : 'false').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(normalized)) return true;
  if (['false', '0', 'no', 'off'].includes(normalized)) return false;
  return fallback;
};
const isSafePublicHttps = (value) => {
  try {
    const parsed = new URL(value);
    const host = parsed.hostname.toLowerCase().replace(/^\[|\]$/g, '');
    const privateHost = host === 'localhost' || host === '0.0.0.0' || host.endsWith('.local') || host.includes(':') || /^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host) || /^169\.254\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host);
    return parsed.protocol === 'https:' && !parsed.username && !parsed.password && !privateHost;
  } catch {
    return false;
  }
};

const LOCAL_INTEGRATIONS = {
  runbook_enabled: '',
  runbook_webhook_url: '',
  status_page_webhook_url: '',
  on_call_webhook_url: ''
};
const setting = (name, localKey, fallback = '') => {
  let candidate;
  try { candidate = $vars?.[name]; } catch {}
  if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') return candidate;
  try { candidate = $env?.[name]; } catch {}
  if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') return candidate;
  candidate = LOCAL_INTEGRATIONS[localKey];
  return candidate !== undefined && candidate !== null && String(candidate).trim() !== '' ? candidate : fallback;
};

const demoMode = data.config.demo_mode;
const integrations = {
  runbook_enabled: boolean(setting('PULSEOPS_RUNBOOK_ENABLED', 'runbook_enabled', demoMode ? 'true' : 'false'), demoMode),
  runbook_webhook_url: text(setting('PULSEOPS_RUNBOOK_WEBHOOK_URL', 'runbook_webhook_url', demoMode ? 'https://automation.example.com/v1/runbooks/restart-service' : '')),
  status_page_webhook_url: text(setting('PULSEOPS_STATUS_PAGE_WEBHOOK_URL', 'status_page_webhook_url', demoMode ? 'https://status-api.example.com/v1/incidents' : '')),
  on_call_webhook_url: text(setting('PULSEOPS_ON_CALL_WEBHOOK_URL', 'on_call_webhook_url', demoMode ? 'https://oncall.example.com/v1/events' : ''))
};

if (!demoMode) {
  const required = ['status_page_webhook_url', 'on_call_webhook_url'];
  if (integrations.runbook_enabled) required.push('runbook_webhook_url');
  const missing = required.filter(key => !integrations[key]);
  if (missing.length) throw new Error(`Missing live integration configuration: ${missing.join(', ')}`);
  for (const key of required) {
    if (!isSafePublicHttps(integrations[key])) throw new Error(`${key} must use a safe public HTTPS URL`);
  }
}

return [{ json: { ...data, config: { ...data.config, integrations } } }];

const store = $getWorkflowStaticData('global');
